--
-- Table structure for table `employees`
--

DROP TABLE IF EXISTS `employees`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `employees` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `branch_id` int(11) NOT NULL,
  `employee_code` varchar(20) NOT NULL,
  `full_name` varchar(150) NOT NULL,
  `position` varchar(100) DEFAULT NULL COMMENT 'Chức vụ / Bộ phận',
  `phone` varchar(30) DEFAULT NULL,
  `salary_type` enum('FIXED','HOURLY') NOT NULL COMMENT 'FIXED = Lương cứng, HOURLY = Lương theo giờ',
  `base_salary` decimal(12,2) DEFAULT 0.00 COMMENT 'Mức lương tháng (Lương cứng)',
  `hourly_rate` decimal(12,2) DEFAULT 0.00 COMMENT 'Đơn giá ca (Lương giờ)',
  `overtime_rate` decimal(12,2) DEFAULT 120000.00 COMMENT 'Đơn giá tăng ca / ca tối',
  `attendance_allowance` decimal(12,2) DEFAULT 0.00 COMMENT 'Phụ cấp chuyên cần',
  `boarding_allowance` decimal(12,2) DEFAULT 0.00 COMMENT 'Phụ cấp Bán Trú (đơn giá hoặc cố định)',
  `travel_allowance` decimal(12,2) DEFAULT 0.00 COMMENT 'Thưởng đi lại / Phụ cấp xăng xe',
  `has_lunch_allowance` tinyint(1) DEFAULT 1 COMMENT '1 = Nhận cơm 25k/ngày, 0 = Không nhận',
  `other_allowance` decimal(12,2) DEFAULT 0.00 COMMENT 'Phụ cấp khác',
  `time_frame` varchar(100) DEFAULT NULL COMMENT 'Khung giờ hợp đồng (VD: 8:00 - 17:30)',
  `standard_hours` decimal(4,2) DEFAULT 8.00 COMMENT 'Giờ chuẩn/ngày hoặc số ca chuẩn/buổi',
  `standard_work_days` decimal(4,1) DEFAULT 26.0 COMMENT 'Ngày công chuẩn riêng',
  `default_time_in` time DEFAULT NULL COMMENT 'Giờ vào quy định',
  `default_time_out` time DEFAULT NULL COMMENT 'Giờ ra quy định',
  `work_schedule` varchar(100) DEFAULT 'Thứ 2 - Thứ 7',
  `status` enum('ACTIVE','LEAVE','RESIGNED') DEFAULT 'ACTIVE' COMMENT 'Trạng thái làm việc',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_branch_code_type` (`branch_id`,`employee_code`,`salary_type`),
  CONSTRAINT `employees_ibfk_1` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

