--
-- Table structure for table `monthly_payroll`
--

DROP TABLE IF EXISTS `monthly_payroll`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `monthly_payroll` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `month` int(11) NOT NULL COMMENT '1-12',
  `year` int(11) NOT NULL COMMENT '2026',
  `total_days_x` decimal(5,2) DEFAULT 0.00 COMMENT 'Tổng ngày công X thực tế',
  `total_ot_hours` decimal(5,2) DEFAULT 0.00 COMMENT 'Tổng giờ tăng ca',
  `ot_count` int(11) DEFAULT 0 COMMENT 'Số lần tăng ca',
  `total_slots` decimal(6,2) DEFAULT 0.00 COMMENT 'Tổng số ca dạy (Lương giờ)',
  `total_boarding_days` int(11) DEFAULT 0 COMMENT 'Số buổi bán trú (BT)',
  `standard_work_days` decimal(4,1) DEFAULT 26.0 COMMENT 'Ngày chuẩn áp dụng',
  `late_count` int(11) DEFAULT 0 COMMENT 'Số lần đi trễ',
  `total_late_minutes` int(11) DEFAULT 0 COMMENT 'Tổng phút trễ',
